49 func resolve(id: Variant, version: Variant, hash: Variant, overrides: Dictionary={}, features: Dictionary={}) -> Dictionary:
50 	if typeof(id) not in [TYPE_STRING,TYPE_STRING_NAME] or typeof(version)!=TYPE_INT or typeof(hash)!=TYPE_STRING:return {"error":&"invalid_profile"}
51 	var frozen:=profile(id)
52 	if frozen.is_empty():return {"error":&"invalid_profile"}
53 	if frozen.version!=version or frozen.profile_hash!=hash:return {"error":&"profile_identity_mismatch"}
