71 static func freeze(registry, domain: Variant, simulation: Dictionary, effects: Dictionary={}, diagnostics: Dictionary={}, environment: Dictionary={}, extra_sources: PackedStringArray=PackedStringArray()) -> Dictionary:
72 	if typeof(domain) not in [TYPE_STRING,TYPE_STRING_NAME] or String(domain).is_empty() or String(domain).length()>128:return {"error":&"invalid_configuration_domain"}
73 	if not exact(simulation,SIMULATION_KEYS):return {"error":&"invalid_simulation_flags"}
74 	for value in simulation.values():
75 		if typeof(value)!=TYPE_BOOL:return {"error":&"invalid_simulation_flags"}
76 	if not simulation.unrestricted_sand_tools:return {"error":&"unsupported_inventory_accounting"}
77 	for key in ["enable_structures","rise_front_history","contact_history"]:
78 		if simulation[key]:return {"error":&"unsupported_history_capability"}
79 	var effect:=_flags(effects,EFFECT_DEFAULTS);var diagnostic:=_flags(diagnostics,DIAGNOSTIC_DEFAULTS)
80 	if not effect.error.is_empty():return effect

11 static func load_file(path: String, configuration: Dictionary) -> Dictionary:
12 	var file:=FileAccess.open(path,FileAccess.READ)
13 	if file==null:return {"error":&"open_failed"}
14 	if file.get_length()<48:return {"error":&"invalid_file_size"}
15 	var magic:=file.get_buffer(8).get_string_from_ascii();file.close()
16 	if magic==Codec.MAGIC:return Codec.load(path,configuration)
17 	if magic!=Legacy.Old.MAGIC and magic!=Legacy.Store.MAGIC:return {"error":&"unsupported_checkpoint_family"}
18 	var source:=Legacy.new()
19 	var error:=source.initialize_catalog(CATALOG,CATALOG_SHA256)
20 	if not error.is_empty():return {"error":error}
